def add(sid,n,q,note,cat=None,sub='',level='Explicit'):
 assert q in txt(n),(n,q)
 eid=f'ae_b16_{sid}_{sum(x["school_id"]==sid for x in e)+1:02d}'
 e.append(dict(evidence_id=eid,school_id=sid,source_url=u[n],page_title=title(n),accessed_date=D,quoted_text=q,evidence_type='Official school/provider public description',interpretation_note=note))
 if cat:c.append(dict(code_id=f'ac_b16_{sid}_{sum(x["school_id"]==sid for x in c)+1:02d}',school_id=sid,category=cat,subcategory=sub,coding_level=level,confidence='High' if level=='Explicit' else 'Medium',evidence_id=eid,coder_note='Assistant contextual review; existing codebook v1; 2026-10-30. '+note+' Public claim, not independently verified practice.',review_status='Reviewed'))
